    private TextStyle createStyle(int width, int leftPad, int indent) {
        try {
            TextStyle.Builder builder = TextStyle.builder();
            builder.getClass().getMethod("setMaxWidth", int.class).invoke(builder, width);
            builder.getClass().getMethod("setLeftPad", int.class).invoke(builder, leftPad);
            builder.getClass().getMethod("setIndent", int.class).invoke(builder, indent);
            // Try common build method names
            try {
                return (TextStyle) builder.getClass().getMethod("build").invoke(builder);
            } catch (NoSuchMethodException e) {
                try {
                    return (TextStyle) builder.getClass().getMethod("create").invoke(builder);
                } catch (NoSuchMethodException e2) {
                    return (TextStyle) builder.getClass().getMethod("newInstance").invoke(builder);
                }
            }
        } catch (NoSuchMethodException | IllegalAccessException | InvocationTargetException e) {
            throw new RuntimeException("Failed to create TextStyle via reflection", e);
        }
    }

